'use strict';
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const h = escapeHTML;
const statusNames = {available:'Доступен',issued:'Выдан',accepted:'Принят исполнителем',queued:'В очереди',rejected:'Отказ исполнителя',planned:'Выдан',inProgress:'В работе',paused:'Пауза',aiPending:'Проверяет ИИ',submitted:'На проверке',revision:'Доработка',approved:'Принят мастером',cancelled:'Отменён',superseded:'Предыдущая версия'};
const priorityNames = {urgent:'Аварийный',high:'Высокий',normal:'Обычный',scheduled:'Плановый'};
const roleNames = {worker:'Сотрудник',master:'Мастер смены',admin:'Администратор',manager:'Руководитель'};
const employeeNames = {free:'Свободен',busy:'В работе',queued:'Есть задачи',off:'Не на смене'};
const referenceNames = {sites:'Участки',equipment:'Оборудование',brigades:'Бригады',defect_codes:'Неисправности',materials:'Материалы',work_norms:'Нормативы'};
const paths = {home:'m3 10 9-7 9 7v10H3z M9 20v-7h6v7',tasks:'M5 4h14v17H5z M9 4V2h6v2 M8 10h8 M8 14h8 M8 18h5',reports:'M4 3h11l5 5v13H4z M14 3v6h6 M8 13h8 M8 17h5',schedule:'M4 5h16v16H4z M7 2v6 M17 2v6 M4 10h16 M8 14h2 M14 14h2 M8 18h2',equipment:'M5 8h14v11H5z M8 8V4h8v4 M9 12h6 M9 16h6',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M20 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 4l3 1 M17 5l3-1 M20 20l-3-1 M7 19l-3 1 M3 12h3 M18 12h3 M12 3v3 M12 18v3',close:'M6 6l12 12 M18 6 6 18',check:'m5 12 4 4 10-10',arrow:'M5 12h14 M14 7l5 5-5 5',plus:'M12 5v14 M5 12h14',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M9 21h6',camera:'M3 7h4l2-3h6l2 3h4v13H3z M12 10a3.5 3.5 0 1 0 0 7 3.5 3.5 0 0 0 0-7'};
const icon = name => `<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name] || paths.tasks}"/></svg>`;
const state = {seedDemo:false,token:sessionStorage.getItem('naryadai.token') || '',user:null,snapshot:null,refs:{},page:'home',role:'worker',search:'',filter:'active',priority:'all',busy:false,refreshing:false,network:'connecting',photoURLs:new Map(),reviewDrafts:new Map(),pendingRequests:new Map(),draft:null,taskId:null,dialogVersion:0,installPrompt:null};
request('/health').then(info=>{state.seedDemo=info.seed_demo===true;const button=$('#import-demo');if(button)button.hidden=!state.seedDemo;}).catch(()=>{});
try { state.user = JSON.parse(sessionStorage.getItem('naryadai.user') || 'null'); } catch (_) { sessionStorage.removeItem('naryadai.user'); }
document.documentElement.classList.toggle('reduce-motion', localStorage.getItem('naryadai.motion') === 'reduce');
const clock = () => Date.now() + (state.clockOffset || 0);
const companyDate = () => new Date(clock());
const parseDate = value => new Date(typeof value==='string' && !/(Z|[+-]\d{2}:\d{2})$/.test(value) ? value+'+05:00' : value);
const day = () => companyDate().toLocaleDateString('sv-SE',{timeZone:'Asia/Qyzylorda'});
const uuid = () => crypto.randomUUID ? crypto.randomUUID() : [...crypto.getRandomValues(new Uint8Array(16))].map(n => n.toString(16).padStart(2,'0')).join('');
const dateTime = value => value ? parseDate(value).toLocaleString('ru-RU',{timeZone:'Asia/Qyzylorda',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}) : 'Не задано';
const hour = value => value == null ? '—' : `${String(Math.floor(value)).padStart(2,'0')}:${String(Math.round((value % 1) * 60)).padStart(2,'0')}`;
const asHour = value => { const [a,b] = String(value).split(':').map(Number); return a + b / 60; };
const active = task => !['approved','cancelled'].includes(task.status);
const taskById = id => state.snapshot?.tasks.find(task => task.id === Number(id));
const taskReport = id => state.snapshot?.reports.find(report => report.task_id === Number(id) && report.status !== 'superseded');
const assigned = (task,id) => task.worker_id===id || (task.member_ids||[]).includes(id);
const canManage = () => ['master','admin'].includes(state.user?.role);
const mine = () => state.snapshot?.tasks.filter(task => assigned(task,state.user?.id)) || [];
const refs = category => (state.refs[category] || []).filter(item => item.active !== 0 && item.active !== false);
const badge = (value,type='status') => `<span class="badge ${h(value)}">${h((type === 'priority' ? priorityNames : statusNames)[value] || value)}</span>`;
const deadline = task => {
  if (['aiPending','submitted','approved'].includes(task.status)) return `<span class="deadline">${task.status === 'approved' ? 'Работа принята' : 'Выполнение завершено'}</span>`;
  const delta = Math.round((parseDate(task.deadline).getTime() - clock()) / 60000);
  if (!Number.isFinite(delta)) return '<span>Срок не указан</span>';
  const text = delta < 0 ? `Просрочен на ${delta > -60 ? Math.abs(delta) + ' мин' : Math.ceil(Math.abs(delta) / 60) + ' ч'}` : delta < 60 ? `Осталось ${delta} мин` : delta < 1440 ? `Осталось ${Math.floor(delta / 60)} ч ${delta % 60} мин` : `До ${dateTime(task.deadline)}`;
  return `<span class="deadline ${delta < 0 ? 'overdue' : ''}" title="${h(dateTime(task.deadline))}">${h(text)}</span>`;
};
function toast(message,error=false) { const node = $('#toast'); node.textContent = message; node.classList.toggle('error',error); node.hidden=false; $('#announcer').textContent=message; clearTimeout(toast.timer); toast.timer=setTimeout(() => node.hidden=true,5000); }
function network(value) { state.network=value; const node=$('#network'); if(node) { node.classList.toggle('offline',value==='offline'); node.textContent=value==='online'?'Сервер доступен':value==='offline'?'Нет связи с сервером':'Соединение…'; } }
class APIError extends Error { constructor(message,status=0) { super(message);this.status=status; } }
async function request(path,options={}) {
  const controller=new AbortController(); const timer=setTimeout(() => controller.abort(),30000);
  const sessionToken=state.token;
  try {
    const response=await fetch(path,{...options,signal:controller.signal,cache:'no-store',headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(state.token?{Authorization:`Bearer ${state.token}`} : {}),...options.headers}});
    let data;try{data=await response.json();}catch(_){throw new APIError('Сервер вернул непонятный ответ.',response.status);}
    network('online');
    if(!response.ok){if(response.status===401 && state.user && sessionToken===state.token) await endSession(false);throw new APIError(typeof data.detail==='string'?data.detail:'Проверьте заполнение полей и повторите действие.',response.status);}
    return data;
  } catch(error) {
    if(error instanceof APIError) throw error;
    network('offline');throw new APIError('Нет ответа сервера. Проверьте сеть. Черновик сохранён; отправку нужно повторить вручную.');
  } finally { clearTimeout(timer); }
}
async function rpc(method,args=[],kwargs={},photos=[],requestId=null) {
  const explicit=requestId!==null;const key=JSON.stringify([state.user?.id,method,args,kwargs,photos]);
  const id=explicit?requestId:(state.pendingRequests.get(key)||uuid());
  if(!explicit)state.pendingRequests.set(key,id);
  try {
    const data=await request(`/api/call/${encodeURIComponent(method)}`,{method:'POST',body:JSON.stringify({args,kwargs,photos,request_id:id})});
    if(!explicit)state.pendingRequests.delete(key);return data.result;
  } catch(error) {
    // A timeout / lost response / HTTP 5xx may follow a completed mutation.
    // Reuse the same ID only for a manual retry of the same payload in this session.
    if(!explicit&&error.status>=400&&error.status<500)state.pendingRequests.delete(key);
    throw error;
  }
}
let draftDB;
function database() { return draftDB ||= new Promise((resolve,reject) => {const r=indexedDB.open('naryadai-private-drafts',1);r.onupgradeneeded=() => r.result.createObjectStore('drafts');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);}); }
async function draftGet(key) { const db=await database();return new Promise((resolve,reject) => {const r=db.transaction('drafts').objectStore('drafts').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);}); }
async function draftWrite(key,value) { const sessionToken=state.token;const db=await database();if(!state.user||state.token!==sessionToken)throw new Error('Сеанс завершён.');return new Promise((resolve,reject) => {const tx=db.transaction('drafts','readwrite');tx.objectStore('drafts').put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);}); }
async function draftDelete(key) { const db=await database();return new Promise((resolve,reject) => {const tx=db.transaction('drafts','readwrite');tx.objectStore('drafts').delete(key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);}); }
async function clearDrafts() { try{const db=await database();await new Promise((resolve,reject)=>{const tx=db.transaction('drafts','readwrite');tx.objectStore('drafts').clear();tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}catch(_){/* browser may disallow storage */} }
const draftKey = id => `${state.user.id}:${id}`;
function clearPhotos() { state.photoURLs.forEach(url => URL.revokeObjectURL(url));state.photoURLs.clear(); }
async function endSession(send=true) {
  await NaryadNotifications.stop();
  if(send){try{await request('/api/logout',{method:'POST'});}catch(_){/* local logout always succeeds */}}
  state.token='';state.user=null;state.snapshot=null;state.refs={};state.draft=null;state.taskId=null;
  sessionStorage.removeItem('naryadai.token');sessionStorage.removeItem('naryadai.user');
  await clearDrafts();clearPhotos();state.reviewDrafts.clear();state.pendingRequests.clear();if($('#dialog').open)$('#dialog').close();
  navigator.serviceWorker?.controller?.postMessage('PURGE_PRIVATE');Object.assign(chatState,{cid:'',items:[],conversations:[],draft:'',signature:'',pending:false,replyId:'',replyKey:'',newId:''});consoleMonitor=null;consoleRetry=null;renderLogin();
}
function renderLogin() {
  $('#app').innerHTML=`<main id="main" class="login-wrap"><section class="login-brand"><img src="/assets/branding/km-logo-white.svg" alt="Костанайские Минералы"><div><div class="eyebrow" style="color:#b9d4f7">НарядAI · производственные наряды</div><h1>Каждая работа —<br>под контролем.</h1><p>Наряды, фотоотчёты и решения мастера в одном рабочем пространстве.</p></div><div class="login-steps"><span>Выдать наряд</span><span>Выполнить работу</span><span>Принять результат</span></div></section><section class="login-form-wrap"><form id="login-form" class="login-form"><h2>Вход в рабочую смену</h2><p class="muted">Выберите роль и войдите под своей учётной записью.</p><div class="roles" role="group" aria-label="Роль">${Object.entries(roleNames).map(([key,value])=>`<button type="button" data-role="${key}" aria-pressed="${key===state.role}">${h(key==='master'?'Мастер':value)}</button>`).join('')}</div><div class="field"><label for="username">Логин</label><input id="username" name="username" autocomplete="username" required maxlength="100"></div><div class="field"><label for="password">Пароль</label><input id="password" name="password" type="password" autocomplete="current-password" required maxlength="300"></div><p id="login-error" class="error-text" role="alert"></p><button class="primary" type="submit">Войти ${icon('arrow')}</button><p class="sync-note">Подключение к серверу предприятия. ИИ помогает проверке, окончательное решение принимает мастер.</p></form></section></main>`;
  $$('[data-role]').forEach(button => button.onclick=()=>{state.role=button.dataset.role;$$('[data-role]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));});
  $('#login-form').onsubmit=async event=>{event.preventDefault();const button=$('#login-form button[type=submit]');button.disabled=true;$('#login-error').textContent='';try{const data=await request('/api/login',{method:'POST',body:JSON.stringify({username:$('#username').value,password:$('#password').value,role:state.role})});await clearDrafts();state.token=data.token;state.user=data.user;sessionStorage.setItem('naryadai.token',data.token);sessionStorage.setItem('naryadai.user',JSON.stringify(data.user));state.page='home';renderShell();await refresh(true);}catch(error){$('#login-error')&&($('#login-error').textContent=error.message);}finally{if(button.isConnected)button.disabled=false;}};
}
function baseNavItems() { return state.user.role==='worker' ? [['home','Главная'],['tasks','Наряды'],['schedule','График'],['reports','Результаты'],['settings','Настройки']] : state.user.role==='master' ? [['home','Обзор'],['tasks','Наряды'],['reports','Приёмка'],['equipment','Оборудование'],['people','Команда'],['analytics','Аналитика'],['settings','Настройки']] : state.user.role==='admin' ? [['home','Обзор'],['tasks','Наряды'],['reports','Приёмка'],['equipment','Справочники'],['people','Доступ'],['analytics','Аналитика'],['settings','Настройки']] : [['home','Обзор'],['tasks','Наряды'],['reports','Отчёты'],['equipment','Оборудование'],['people','Команда'],['analytics','Аналитика'],['settings','Настройки']]; }
function navItems() {const items=baseNavItems();if(state.user.role!=='worker')items.splice(items.length-1,0,['chat','Чат с ИИ']);if(state.user.role==='admin')items.splice(items.length-1,0,['console','Контроль'],['knowledge','Документация']);return items;}
function mobileNavItems() {return state.user.role==='worker'?[['home','Смена'],['tasks','Наряды'],['schedule','График'],['settings','Профиль']]:state.user.role==='admin'?[['home','Обзор'],['chat','Чат с ИИ'],['console','Контроль'],['more','Ещё']]:[['home','Смена'],['tasks','Наряды'],['reports','Приёмка'],['more','Ещё']];}
function morePage(){return pageHead('Рабочее пространство','Разделы вашей роли')+`<div class="grid cols-3">${navItems().map(([key,name])=>`<button class="card menu-tile" data-go="${key}">${icon(key)} ${h(name)}</button>`).join('')}</div>`;}
function renderShell() {
  const list=navItems();$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="/assets/branding/km-logo-white.svg" alt="Костанайские Минералы"><strong>НарядAI</strong><small>Управление работами</small></div><nav class="nav" aria-label="Основная навигация">${list.map(([key,name])=>`<button data-page="${key}" ${state.page===key?'aria-current="page"':''}>${icon(key)}<span>${h(name)}</span></button>`).join('')}</nav><div class="side-bottom"><small>${h(roleNames[state.user.role])}<br>АО «Костанайские Минералы»</small><button id="side-logout">Завершить сеанс</button></div></aside><div class="main-wrap"><header class="topbar"><div><strong>${h(state.user.name)}</strong><small>${h(state.user.job || roleNames[state.user.role])}</small></div><div class="topbar-actions"><span id="network" class="network" role="status">Соединение…</span><button id="notification-bell" class="notification-bell" aria-label="Уведомления">${icon('bell')}<span id="notification-count" hidden>0</span></button></div></header><main class="main" id="main" tabindex="-1"><div class="grid cols-3">${Array(3).fill('<div class="skeleton" aria-label="Загрузка"></div>').join('')}</div></main></div></div>`;
  $('.shell').insertAdjacentHTML('beforeend',`<nav class="mobile-nav" aria-label="Навигация смены">${mobileNavItems().map(([key,name])=>`<button data-page="${key}" ${state.page===key?'aria-current="page"':''}>${icon(key)}<span>${h(name)}</span></button>`).join('')}</nav>`);
  $$('[data-page]').forEach(button=>button.onclick=()=>go(button.dataset.page));$('#side-logout').onclick=()=>endSession();$('#notification-bell').onclick=()=>go('notifications');network(state.network);
}
function go(page) { state.page=page;state.search='';state.filter='active';$$('[data-page]').forEach(button=>button.toggleAttribute('aria-current',button.dataset.page===page));$$('[data-page][aria-current]').forEach(button=>button.setAttribute('aria-current','page'));renderPage();$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'auto'}); }
async function refresh(first=false) {
  if(!state.user)return;if(state.refreshing){if(first)state.refreshAgain=true;return;}state.refreshing=true;
  const sessionToken=state.token;
  try {
    const snapshot=await request(`/api/snapshot?day=${day()}`);if(!state.user||sessionToken!==state.token)return;state.snapshot=snapshot;if(Number.isFinite(snapshot.server_time))state.clockOffset=snapshot.server_time*1000-Date.now();
    if(first || !Object.keys(state.refs).length)state.refs=await request('/api/catalogs');
    updateNotificationCount();NaryadNotifications.feed(snapshot.notifications||[],state.user);
    if(first)openPendingNotification();
    const main=$('#main');const editing=['chat','console','knowledge'].includes(state.page)||(document.activeElement?.matches('input,select,textarea,button,a') && Boolean(document.activeElement.closest('#main'))) || $('#dialog').open;
    if(first || !editing){const scroll=window.scrollY;renderPage();if(!first)window.scrollTo({top:scroll,behavior:'auto'});}
    else { const node=$('#sync-time');if(node)node.textContent=`Данные обновлены ${new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}`; }
    updateOpenReport();
  } catch(error) { if(first && $('#main'))$('#main').innerHTML=`<div class="notice error" role="alert">${h(error.message)}</div><button id="retry-load">Повторить подключение</button>`;if($('#retry-load'))$('#retry-load').onclick=()=>refresh(true); }
  finally { state.refreshing=false;if(state.refreshAgain){state.refreshAgain=false;refresh(true);} }
}
function pageHead(title,subtitle,actions='') { return `<div class="page-head"><div><div class="eyebrow">${h(roleNames[state.user.role])}</div><h1>${h(title)}</h1><p>${h(subtitle)}</p></div>${actions}</div>`; }
function empty(title,text='') { return `<div class="empty">${icon('check')}<strong>${h(title)}</strong>${h(text)}</div>`; }
function metric(value,label) { return `<div class="card metric"><b>${h(value)}</b><span>${h(label)}</span></div>`; }
function taskCard(task) { return `<button class="card task-card" data-task="${task.id}"><span class="task-id">НАРЯД НР-${task.id}</span><h3>${h(task.title)}</h3><div class="badges">${badge(task.status)}${badge(task.priority,'priority')}</div><small>${h(task.equipment)} · ${h(task.site)}</small><div class="task-meta">${deadline(task)}<span>${h(task.duration)} ч</span></div>${state.user.role!=='worker'?`<small style="margin-top:10px">${h(task.worker_name || 'Исполнитель не назначен')}</small>`:''}</button>`; }
function alertsBlock() {
  const items=state.snapshot?.notifications||[];if(!items.length)return '';
  return `<section class="card"><div class="section-head"><h2>Требуют внимания</h2><button data-go="notifications">Все · ${items.length}</button></div><div class="list">${items.slice(0,3).map(notificationRow).join('')}</div></section>`;
}
function updateNotificationCount() {
  const count=state.snapshot?.notifications?.length||0;const badge=$('#notification-count');
  if(badge){badge.textContent=count>99?'99+':String(count);badge.hidden=!count;}
  $('#notification-bell')?.setAttribute('aria-label',`Уведомления: ${count}`);
}
function notificationRow(item) {
  return `<article class="notification-row ${h(item.severity||'info')}"><div class="notification-symbol">${icon(item.kind==='next_task'?'arrow':item.kind==='overdue'||item.kind==='deadline_reminder'?'clock':'bell')}</div><div class="notification-copy"><strong>${h(item.title||item.payload?.title||'Уведомление')}</strong><p class="work-text">${h(item.body||item.payload?.reason||item.payload?.comment||'')}</p><small>${h(dateTime(item.created_at))}</small><div class="notification-actions">${item.task_id?`<button data-notification-task="${item.task_id}">Открыть наряд</button>`:''}<button class="ghost" data-ack="${item.id}">Прочитано</button></div></div></article>`;
}
function notificationSettings() {
  const enabled=NaryadNotifications.enabled(state.user);
  return `<section class="card"><div class="section-head"><div><h2>Уведомления устройства</h2><p class="muted">${h(NaryadNotifications.status(state.user))}</p></div>${icon('bell')}</div><p>Срочные наряды, приближение срока, сообщения мастера и следующая работа.</p><button id="enable-notifications" class="${enabled?'':'primary'}">${enabled?'Выключить всплывающие':'Включить уведомления'}</button><p class="sync-note">Держите приложение открытым. При закрытом браузере или спящем устройстве сообщения появятся после возвращения. Центр уведомлений работает независимо от разрешения браузера.</p></section>`;
}
function notificationsPage() {
  const items=state.snapshot?.notifications||[];
  const sorted=[...items].sort((a,b)=>Number(b.severity==='critical')-Number(a.severity==='critical')||b.id-a.id);
  return pageHead('Уведомления','Все назначения и сообщения вашей смены.',canManage()?'<button class="primary" id="send-announcement">'+icon('plus')+' Оповестить сотрудников</button>':'')+`<div class="notification-layout"><section class="card"><div class="section-head"><h2>Непрочитанные · ${items.length}</h2>${items.length?'<button id="read-all-notifications">Прочитать все</button>':''}</div><div class="list">${sorted.map(notificationRow).join('')||empty('Вы всё прочитали','Здесь появятся новые наряды, сообщения и напоминания.')}</div></section>${notificationSettings()}</div>`;
}
function composeAnnouncement() {
  const workers=state.snapshot.users.filter(u=>u.role==='worker'&&u.active);
  showDialog('Оповестить сотрудников','Сообщение появится в приложении и в уведомлениях устройства',`<form id="announcement-form"><div class="field"><label for="announcement-recipient">Кому</label><select id="announcement-recipient"><option value="">Всем сотрудникам (${workers.length})</option>${workers.map(u=>`<option value="${u.id}">${h(u.name)}</option>`).join('')}</select></div>${field('announcement-title','Заголовок','text','','required minlength="3" maxlength="120"')}<div class="field"><label for="announcement-message">Сообщение</label><textarea id="announcement-message" minlength="3" maxlength="2000" required placeholder="Например: сбор бригады в 15:00 у мастерской"></textarea></div><label class="settings-row"><span>Важное сообщение</span><input type="checkbox" id="announcement-important"></label><div id="form-error" class="error-text" role="alert"></div><div class="dialog-actions"><button class="primary">Отправить оповещение</button></div></form>`);
  $('#announcement-form').onsubmit=event=>{event.preventDefault();const uid=$('#announcement-recipient').value;mutate($('#announcement-form button'),'send_announcement',[],{title:$('#announcement-title').value,message:$('#announcement-message').value,user_ids:uid?[Number(uid)]:null,important:$('#announcement-important').checked});};
}
async function openNotificationTask(id) {
  let task=taskById(id);
  try{if(!task){task=await rpc('task',[Number(id)]);state.snapshot.tasks.push(task);}openTask(Number(id));}
  catch(error){toast(error.message,true);}
}
let pendingNotification=null;
function openPendingNotification() {
  const params=new URLSearchParams(location.search);
  if(!pendingNotification&&(params.has('notificationTask')||params.has('notifications'))){pendingNotification={taskId:Number(params.get('notificationTask'))||null};history.replaceState(null,'',location.pathname);}
  if(!pendingNotification||!state.user||!state.snapshot)return;
  if($('#dialog').open){toast('Новое уведомление — откройте колокольчик после сохранения формы.');return;}
  const target=pendingNotification;pendingNotification=null;
  if(target.userId&&target.userId!==state.user.id){go('notifications');return;}
  if(target.taskId)openNotificationTask(target.taskId);else go('notifications');
}
window.addEventListener('naryadai-notification',event=>{pendingNotification=event.detail;openPendingNotification();});
navigator.serviceWorker?.addEventListener('message',event=>{if(event.data?.type==='OPEN_NOTIFICATION'){pendingNotification=event.data;openPendingNotification();}});

function homePage() {
  const tasks=state.user.role==='worker'?mine():state.snapshot.tasks;const todo=tasks.filter(active);const reports=state.snapshot.reports.filter(r=>r.status==='submitted');const inWork=todo.filter(t=>t.status==='inProgress');const waiting=todo.filter(t=>t.status==='planned');
  const metricRow=state.snapshot.metrics?.find(m=>m.id===state.user.id);const finished=state.snapshot.reports.filter(r=>r.status==='approved');const avg=metricRow?.score??'—';
  if(state.user.role==='worker'){
    const current=inWork[0] || todo.find(t=>['paused','revision'].includes(t.status)) || waiting[0] || todo[0];
    return pageHead('Моя смена',new Date().toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'}))+`<div class="grid cols-2 worker-focus"><section class="card hero-card"><div class="eyebrow" style="color:#b9d4f7">Следующее действие</div>${current?`<small class="hero-id">НР-${current.id} · текущая работа</small><h2>${h(current.title)}</h2><div class="badges">${badge(current.status)}${badge(current.priority,'priority')}</div><p class="muted">${h(current.equipment)} · ${h(current.site)}</p><p>${deadline(current)}</p><button class="primary" data-task="${current.id}">${h(primaryAction(current)?.label || 'Открыть наряд')}${icon('arrow')}</button>`:`<h2>Текущих нарядов нет</h2><p class="muted">Новые назначения появятся здесь. Доступные работы можно найти во вкладке «Наряды».</p><button class="primary" data-go="tasks">Посмотреть наряды</button>`}</section><section class="card"><h2>Ближайшие работы</h2><div class="list">${todo.filter(t=>t.id!==current?.id).slice(0,3).map(t=>`<div class="list-row"><div><strong>${h(t.title)}</strong><small>${h(t.equipment)}</small>${deadline(t)}</div><button data-task="${t.id}" aria-label="Открыть наряд ${t.id}">${icon('arrow')}</button></div>`).join('') || empty('График свободен','Здесь появятся следующие назначенные работы.')}</div></section>${alertsBlock()}</div><div class="metric-row worker-stats">${metric(todo.filter(t=>['planned','accepted','queued'].includes(t.status)).length,'В очереди')}${metric(mine().filter(t=>['submitted','aiPending'].includes(t.status)).length,'На проверке')}</div>`;
  }
  const overdue=todo.filter(t=>!['submitted','aiPending'].includes(t.status)&&parseDate(t.deadline).getTime()<clock()).length;
  const urgent=todo.filter(t=>t.priority==='urgent').length;
  const attention=state.attention?.failures?.filter(x=>x.repairs>1).map(x=>({...x,equipment:refs('equipment').find(e=>e.id===x.equipment_id)?.name,summary:`${x.repairs} ремонтов · требуется анализ мастера`})) || [];
  const pauses=todo.filter(t=>t.status==='paused').map(t=>({...t,task_id:t.id,reason:'Работа приостановлена',minutes:0}));
  return pageHead('Пульс смены','Выдавайте наряды и принимайте результаты в одном пространстве.',canManage()?`<button class="primary" id="create-task">${icon('plus')} Выдать наряд</button>`:'')+`<div class="metric-row">${metric(todo.length,'Активных нарядов')}${metric(urgent,'Аварийных работ')}${metric(reports.length,'Отчётов на приёмке')}${metric(overdue,'Просроченных работ')}</div><div class="grid cols-2"><section class="card"><div class="section-head"><h2>Приёмка результатов</h2><button data-go="reports">Все отчёты</button></div><div class="list">${reports.slice(0,4).map(report=>`<div class="list-row"><div><strong>${h(report.title)}</strong><small>${h(report.worker_name)} · ${h(report.equipment)}</small><span class="badge">${report.ai?.status==='completed'?'Проверка ИИ готова':'Ручная проверка'}</span></div><button data-report="${report.id}">Проверить</button></div>`).join('')||empty('Всё проверено','Новые отчёты появятся после отправки сотрудником.')}</div></section><section class="card"><div class="section-head"><h2>Команда на смене</h2><button data-go="people">Загрузка</button></div><div class="list">${state.snapshot.users.filter(p=>p.role==='worker'&&p.active).slice(0,4).map(person=>personRow(person)).join('')}</div></section>${alertsBlock()}${pauses.length?`<section class="card"><h2>Приостановленные работы</h2><div class="list">${pauses.slice(0,5).map(pause=>`<div class="list-row"><div><strong>${h(pause.equipment)}</strong><small>${h(pause.reason)} · причина в истории</small></div><button data-task="${Number(pause.task_id)}">Наряд</button></div>`).join('')}</div></section>`:''}<section class="card"><h2>Оборудование: точки внимания</h2><div class="list">${attention.slice(0,4).map(item=>`<div class="list-row"><div><strong>${h(item.equipment || item.name)}</strong><small>${h(item.summary || (item.defects || []).map(defect=>`${defect.defect}: ${defect.count} раза`).join(' · ') || `${item.task_ids?.length || 0} связанных работ`)}</small></div><button data-equipment="${item.equipment_id}">История</button></div>`).join('')||empty('История за весь период','Откройте «Аналитика», чтобы увидеть частые ремонты по всей БД.')}</div></section></div>`;
}
function personRow(person,detail=false) {
  const tasks=state.snapshot.tasks.filter(t=>assigned(t,person.id)&&active(t));const status=state.snapshot.employee_status[String(person.id)] || 'off';const accepted=state.snapshot.reports.filter(r=>r.worker_id===person.id&&r.status==='approved');const stats=state.snapshot.metrics?.find(m=>m.id===person.id);const average=stats?.score??null;
  return `<div class="list-row"><div class="person"><span class="avatar">${h(person.name.split(' ').map(v=>v[0]).slice(0,2).join(''))}</span><div><strong>${h(person.name)}</strong><small>${h(detail?person.job:employeeNames[status])}</small>${detail?`<small>${stats?.done||0} закрыто за 90 дней · ${average===null?'нет оценок':average+'/100'} · ${tasks.length} активных</small>`:''}</div></div><div><span class="badge"><i class="employee-dot ${h(status)}"></i>${h(employeeNames[status])}</span><small>${tasks.length} нарядов · ${tasks.reduce((sum,t)=>sum+Number(t.duration),0)} ч</small></div></div>`;
}
function tasksPage() {
  return pageHead('Наряды',state.user.role==='worker'?'Назначенные и доступные работы. Статус и срочность показаны отдельно.':'Назначения, сроки и движение работ.',canManage()?'<button class="primary" id="create-task">Выдать наряд</button>':'')+`<div class="filters"><input id="task-search" type="search" placeholder="Номер, оборудование или название" aria-label="Поиск наряда" value="${h(state.search)}"><select id="task-filter" aria-label="Фильтр статусов"><option value="active">Текущие</option><option value="mine">Назначены мне</option><option value="available">Доступные</option><option value="submitted">На проверке</option><option value="approved">Завершённые</option><option value="all">Все статусы</option></select><select id="task-priority" aria-label="Фильтр приоритета"><option value="all">Все приоритеты</option>${Object.entries(priorityNames).map(([key,value])=>`<option value="${key}">${h(value)}</option>`).join('')}</select></div><div id="task-list" class="grid cols-3"></div>`;
}
function updateTaskList() {
  const tasks=state.snapshot.tasks.filter(task=>{
    const match=`${task.id} ${task.title} ${task.equipment} ${task.site}`.toLowerCase().includes(state.search.toLowerCase());
    const status=state.filter==='all'||state.filter==='active'&&active(task)||state.filter==='mine'&&assigned(task,state.user.id)&&active(task)||state.filter===task.status;
    return match&&status&&(state.priority==='all'||task.priority===state.priority);
  });$('#task-list').innerHTML=tasks.map(taskCard).join('')||empty('Наряды не найдены','Попробуйте другой фильтр или дождитесь назначения мастера.');bindCommon($('#task-list'));
}
function reportsPage() {
  const reports=state.snapshot.reports.filter(r=>r.status!=='superseded'&&(state.user.role==='worker'||['submitted','aiPending','revision'].includes(r.status)));
  return pageHead(state.user.role==='worker'?'Мои результаты':'Приёмка работ',state.user.role==='worker'?'Отзывы мастера и состояние отправленных отчётов.':'Рекомендация ИИ помогает проверке. Решение и оценка остаются за мастером.')+`<div class="grid cols-3">${reports.map(report=>`<button class="card task-card" data-report="${report.id}"><span class="task-id">ОТ-${report.id} · НР-${report.task_id}</span><h3>${h(report.title)}</h3><div class="badges">${badge(report.status)}${report.score!=null?`<span class="badge approved">${report.score}/100</span>`:''}</div><small>${h(report.worker_name)} · ${h(report.equipment)}</small><div class="task-meta"><span>${h(dateTime(report.created))}</span><span>${h(report.hours)} ч</span></div></button>`).join('')||empty('Отчётов пока нет','Они появятся после выполнения и отправки работы.')}</div>`;
}
function schedulePage() {
  const tasks=mine().filter(t=>t.day===day()&&active(t)).sort((a,b)=>(a.start??24)-(b.start??24));const shift=state.snapshot.shifts[String(state.user.id)];
  return pageHead('Мой график','Работы на сегодня. Завершение выполнения и ожидание проверки показаны отдельно.')+`<div class="card"><div class="section-head"><h2>Сегодня · ${shift?`${hour(shift.start)}–${hour(shift.end)}`:'Смена не назначена'}</h2><span class="badge">${tasks.length} нарядов</span></div><div class="hours">${tasks.map(task=>`<div class="hour-block ${h(task.priority)}"><div><strong>${task.start!=null?hour(task.start)+'–'+hour(task.start+task.duration):'Время согласовать'}</strong><small>${h(task.title)}</small><small>${h(task.equipment)}</small><div class="badges" style="margin-top:8px;margin-bottom:0">${badge(task.status)}${badge(task.priority,'priority')}</div></div><button data-task="${task.id}" aria-label="Открыть наряд ${task.id}">${icon('arrow')}</button></div>`).join('')||empty('На сегодня работ нет','Назначенные работы появятся здесь.')}</div></div>`;
}
function equipmentPage() {
  if(state.user.role==='admin')return referencesPage(state.referenceCategory || 'sites');
  return pageHead('Оборудование','История по инвентарному номеру, включая наряды за весь период.')+`<div class="grid cols-3">${refs('equipment').map(e=>`<button class="card task-card" data-equipment="${e.id}"><h3>${h(e.name)}</h3><small>${h(e.inventory_number)} · ${h(refs('sites').find(x=>x.id===e.site_id)?.name)}</small><span class="badge">${state.snapshot.tasks.filter(t=>t.equipment_id===e.id&&active(t)).length} активных</span></button>`).join('')}</div>`;
}
function referencesPage(category='sites') {
  state.referenceCategory=category;const items=state.refs[category]||[];
  return pageHead('Справочники','Связанные данные для выдачи нарядов и фотоотчётов.','<button class="primary" id="new-reference">Добавить</button>')+`<div class="notice">Состав бригад и график задаёт администратор. Публичные сведения нужно сверить с предприятием; они не подтверждают наличие конкретного оборудования или закупку материала.</div><div class="reference-tabs">${Object.entries(referenceNames).map(([key,value])=>`<button data-reference-tab="${key}" class="${category===key?'active':''}">${h(value)}</button>`).join('')}</div><div class="references-list">${items.map(item=>`<div class="reference-item"><div class="${item.active===0?'inactive':''}"><strong>${h(item.name || item.equipment_type+' · '+item.kind)}</strong><small>${h([item.code,item.inventory_number,item.unit,category==='materials'?(item.unit_price_known===false?'Цена не подтверждена':Number(item.unit_price)+' тг'):'',item.reference_only?'Открытый справочник':'',item.hours?item.hours+' ч':'',item.active===0?'Отключён':''].filter(Boolean).join(' · '))}</small></div><button data-reference="${h(item.id)}" aria-label="Изменить ${h(item.name)}">${icon('settings')}</button></div>`).join('')||empty('Справочник пуст','Добавьте первую запись.')}</div>`;
}
function peoplePage() {
  const people=state.snapshot.users.filter(p=>state.user.role==='admin'||p.role==='worker');
  return pageHead(state.user.role==='admin'?'Пользователи и доступ':'Команда',state.user.role==='admin'?'Роли и доступ к рабочему пространству.':'Загрузка исполнителей и оценки принятых работ.',state.user.role==='admin'?'<button id="add-user" class="primary">Добавить пользователя</button>':'')+`<section class="card"><div class="list">${people.map(person=>state.user.role==='admin'?`<div class="list-row"><div><strong>${h(person.name)}</strong><small>${h(person.username)} · ${h(roleNames[person.role])} · ${person.active?'Активен':'Отключён'}</small></div>${person.role==='worker'?`<button data-profile="${person.id}">Профиль и бригада</button>`:''}${person.id!==state.user.id?`<button data-user-active="${person.id}" data-active="${person.active?0:1}">${person.active?'Отключить':'Включить'}</button>`:''}</div>`:personRow(person,true)).join('')}</div></section>`;
}
function settingsPage() {
  return pageHead('Настройки','Параметры интерфейса, подключения и сеанса.')+`<div class="grid cols-equal">${notificationSettings()}<section class="card"><h2>Интерфейс</h2><label class="settings-row" for="reduce-motion"><div>Уменьшить анимации<small style="display:block">Настройка сохраняется на этом устройстве</small></div><input type="checkbox" id="reduce-motion" ${document.documentElement.classList.contains('reduce-motion')?'checked':''}></label><div class="settings-row"><div>Установить приложение<small style="display:block">Доступно в поддерживаемом браузере по HTTPS</small></div><button id="install-app" ${state.installPrompt?'':'disabled'}>Установить</button></div><p class="sync-note">На iPhone: «Поделиться» → «На экран Домой». На Android: меню браузера → «Установить приложение».</p></section><section class="card"><h2>Рабочий сеанс</h2><p><strong>${h(state.user.name)}</strong><br><span class="muted">${h(roleNames[state.user.role])}</span></p><p>ИИ ${state.snapshot.ai_enabled?'подключён для предварительной проверки':'выключен: отчёты проверяет мастер вручную'}.</p><div class="notice">Без сети можно открыть оболочку и сохранённый черновик в текущем сеансе. Наряды, фотографии сервера и отправка требуют подключения. Автоматической фоновой отправки нет.</div><button id="settings-logout" class="danger">Выйти и удалить черновики</button></section></div>`;
}
function renderPage() {
  if(!state.snapshot || !state.user)return;
  const pages={chat:chatPage,console:consolePage,knowledge:knowledgePage,more:morePage,home:homePage,tasks:tasksPage,reports:reportsPage,schedule:schedulePage,equipment:equipmentPage,people:peoplePage,settings:settingsPage,notifications:notificationsPage,analytics:analyticsPage};
  $('#main').innerHTML=(pages[state.page]||homePage)()+`<p class="sync-note" id="sync-time">Данные обновлены ${new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})} · обновление каждые 3 секунды</p>`;bindPage();
}
function bindCommon(root=document) {
  $$('[data-task]',root).forEach(button=>button.onclick=()=>openTask(Number(button.dataset.task)));
  $$('[data-report]',root).forEach(button=>button.onclick=()=>openReport(Number(button.dataset.report)));
  $$('[data-notification-task]',root).forEach(button=>button.onclick=()=>openNotificationTask(Number(button.dataset.notificationTask)));
  $$('[data-go]',root).forEach(button=>button.onclick=()=>go(button.dataset.go));
  $$('[data-equipment]',root).forEach(button=>button.onclick=()=>openEquipment(button.dataset.equipment));
  $$('[data-evidence]',root).forEach(button=>button.onclick=()=>openReport(Number(button.dataset.evidence)));
}
function bindPage() {
  bindWorkspace();bindCommon($('#main'));$$('[data-profile]').forEach(b=>b.onclick=()=>editEmployee(state.snapshot.users.find(p=>p.id===Number(b.dataset.profile))));if($('#analytics-form'))$('#analytics-form').onsubmit=event=>{event.preventDefault();calculateAnalytics();};if($('#create-task'))$('#create-task').onclick=()=>createTask();
  if($('#task-list')){ $('#task-filter').value=state.filter;$('#task-priority').value=state.priority;$('#task-search').oninput=event=>{state.search=event.target.value;updateTaskList();};$('#task-filter').onchange=event=>{state.filter=event.target.value;updateTaskList();};$('#task-priority').onchange=event=>{state.priority=event.target.value;updateTaskList();};updateTaskList(); }
  $$('[data-ack]').forEach(button=>button.onclick=()=>mutate(button,'acknowledge_notification',[Number(button.dataset.ack)]));
  if($('#send-announcement'))$('#send-announcement').onclick=composeAnnouncement;
  if($('#read-all-notifications'))$('#read-all-notifications').onclick=()=>mutate($('#read-all-notifications'),'acknowledge_notifications',[(state.snapshot.notifications||[]).map(item=>item.id)]);
  if($('#enable-notifications'))$('#enable-notifications').onclick=async event=>{const button=event.currentTarget;button.disabled=true;try{if(NaryadNotifications.enabled(state.user))await NaryadNotifications.disable(state.user);else await NaryadNotifications.enable(state.user);renderPage();}catch(error){toast(error.message,true);button.disabled=false;}};
  $$('[data-reference-tab]').forEach(button=>button.onclick=()=>{$('#main').innerHTML=referencesPage(button.dataset.referenceTab);bindPage();});
  $$('[data-reference]').forEach(button=>button.onclick=()=>editReference((state.refs[state.referenceCategory]||[]).find(item=>String(item.id)===button.dataset.reference)));
  if($('#new-reference'))$('#new-reference').onclick=()=>editReference();
  if($('#add-user'))$('#add-user').onclick=()=>addUser();
  $$('[data-user-active]').forEach(button=>button.onclick=()=>mutate(button,'set_active',[Number(button.dataset.userActive),Boolean(Number(button.dataset.active))]));
  if($('#reduce-motion'))$('#reduce-motion').onchange=event=>{document.documentElement.classList.toggle('reduce-motion',event.target.checked);localStorage.setItem('naryadai.motion',event.target.checked?'reduce':'auto');};
  if($('#settings-logout'))$('#settings-logout').onclick=()=>endSession();
  if($('#install-app'))$('#install-app').onclick=async()=>{if(state.installPrompt){await state.installPrompt.prompt();state.installPrompt=null;$('#install-app').disabled=true;}};
}
function showDialog(title,subtitle,body) {
  if(state.draft&&state.taskId)persistDraft().catch(()=>toast('Черновик не сохранился. Проверьте свободное место в браузере.',true));
  state.dialogVersion++;state.reportDialog=null;state.taskId=null;state.draft=null;const dialog=$('#dialog');
  dialog.innerHTML=`<div class="dialog-header"><div><small>${h(subtitle)}</small><h2 id="dialog-title">${h(title)}</h2></div><button id="close-dialog" class="ghost" aria-label="Закрыть">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;
  $('#close-dialog').onclick=()=>{if(!state.busy)dialog.close();};if(!dialog.open)dialog.showModal();bindCommon(dialog);return state.dialogVersion;
}
async function mutate(button,method,args=[],kwargs={},photos=[]) {
  if(state.busy)return;state.busy=true;button.disabled=true;
  try{const result=await rpc(method,args,kwargs,photos);toast(method==='send_announcement'?`Оповещение отправлено · получателей: ${result.recipients}`:'Изменения сохранены');$('#dialog').close();await refresh(true);}
  catch(error){toast(error.message,true);const node=$('#form-error');if(node)node.textContent=error.message+(error.status===0||error.status>=500?' При повторе того же действия будет отправлен тот же запрос.':'');}
  finally{state.busy=false;if(button.isConnected)button.disabled=false;}
}
function primaryAction(task) {
  if(state.user.role!=='worker')return null;
  const actions={issued:{label:'Принять наряд',status:'accepted'},accepted:{label:'Начать работу',status:'inProgress'},queued:{label:'Начать работу',status:'inProgress'},planned:{label:'Принять наряд',status:'accepted'},paused:{label:'Продолжить работу',status:'inProgress'},revision:{label:'Доработать отчёт',report:true},inProgress:{label:'Отправить результат',report:true},available:{label:'Взять в график',claim:true}};
  return actions[task.status]||null;
}
async function openTask(id) {
  const task=taskById(id);if(!task)return;const action=primaryAction(task);const report=taskReport(id);
  const step=['issued','accepted','inProgress','submitted','approved'];const stage=['available','issued','planned','rejected'].includes(task.status)?0:['accepted','queued'].includes(task.status)?1:['inProgress','paused','revision'].includes(task.status)?2:['submitted','aiPending'].includes(task.status)?3:4;
  const version=showDialog(task.title,`НАРЯД НР-${task.id}`,`<div class="badges">${badge(task.status)}${badge(task.priority,'priority')}</div><p class="work-text">${h(task.description)}</p><div class="definition"><div><small>Оборудование</small><p>${h(task.equipment)}</p></div><div><small>Участок</small><p>${h(task.site)}</p></div><div><small>Исполнитель</small><p>${h(task.worker_name||'Не назначен')}</p></div><div><small>Срок выполнения</small><p>${h(dateTime(task.deadline))}</p>${deadline(task)}</div><div><small>График · плановое время</small><p>${h(task.day)} · ${hour(task.start)} · ${task.duration} ч</p></div><div><small>Тип работы</small><p>${h(task.kind)}</p></div></div><div class="stepper">${step.map((item,index)=>`<span class="step ${index<=stage?'done':''}">${h({issued:'Выдан',accepted:'Принят',inProgress:'Выполняется',submitted:'Проверка',approved:'Завершён'}[item])}</span>`).join('')}</div>${task.status==='revision'&&report?`<div class="notice warning"><strong>Замечание мастера</strong><br>${h(report.comment)}</div>`:''}${task.status==='aiPending'?'<div class="notice">ИИ проверяет отчёт. Работа уже отправлена; время ожидания проверки не относится к выполнению сотрудником.</div>':''}<div id="form-error" class="error-text" role="alert"></div><div class="toolbar">${action?`<button class="primary" id="primary-task">${h(action.label)}</button>`:''}${task.status==='planned'&&state.user.role==='worker'?'<button id="queue-task">В очередь</button><button id="reject-task" class="danger">Отказ с причиной</button>':''}${task.status==='inProgress'&&state.user.role==='worker'?'<button id="pause-task">Пауза с причиной</button>':''}${report?`<button data-report="${report.id}">Открыть отчёт</button>`:''}${canManage()&&['issued','accepted','queued','planned','available','rejected'].includes(task.status)?'<button id="reassign-task">Переназначить</button>':''}${canManage()&&active(task)&&!['submitted','aiPending'].includes(task.status)?'<button class="danger" id="cancel-task">Отменить</button>':''}${state.user.role!=='worker'?`<button data-equipment="${task.equipment_id}">История оборудования</button>`:''}</div><section class="form-section"><h3>История действий</h3><div id="task-history" class="timeline"><small>Загрузка…</small></div></section>`);
  bindCommon($('#dialog'));
  if($('#primary-task'))$('#primary-task').onclick=()=>action.report?openReportForm(task):action.claim?claimTask(task):mutate($('#primary-task'),'transition',[id,action.status]);
  if($('#queue-task'))$('#queue-task').onclick=()=>mutate($('#queue-task'),'transition',[id,'queued']);
  if($('#reject-task'))$('#reject-task').onclick=()=>reasonAction(task,'rejected','Причина отказа');
  if($('#pause-task'))$('#pause-task').onclick=()=>reasonAction(task,'paused','Причина паузы');
  if($('#cancel-task'))$('#cancel-task').onclick=()=>reasonAction(task,'cancelled','Причина отмены');
  if($('#reassign-task'))$('#reassign-task').onclick=()=>createTask(task);
  try{const events=await rpc('events',[id]);if(version!==state.dialogVersion||!$('#task-history'))return;$('#task-history').innerHTML=events.map(event=>`<div class="timeline-item"><div class="work-text">${h(event.message)}</div><small>${h(event.name)} · ${h(dateTime(event.created))}</small></div>`).join('')||'<small>Нет событий</small>';}catch(error){if($('#task-history'))$('#task-history').textContent=error.message;}
}
function reasonAction(task,status,title) {
  showDialog(title,`НР-${task.id} · ${task.title}`,`<form id="reason-form"><div class="field"><label for="reason">Объясните причину</label><textarea id="reason" minlength="3" maxlength="1000" required placeholder="Например: ожидаем запасную часть"></textarea></div><p class="sync-note">Причина и время сохраняются в истории наряда.</p><div id="form-error" class="error-text" role="alert"></div><div class="dialog-actions"><button type="submit" class="primary">Подтвердить</button></div></form>`);$('#reason-form').onsubmit=event=>{event.preventDefault();mutate($('#reason-form button'),'transition',[task.id,status,$('#reason').value]);};
}
function claimTask(task) {
  const slots=state.snapshot.free_slots[String(state.user.id)]||[];
  showDialog('Взять наряд в график',`НР-${task.id}`,`<form id="claim-form"><p>${h(task.title)} · ${task.duration} ч</p><div class="field"><label for="claim-start">Начало сегодня</label><input id="claim-start" type="time" step="300" required value="${hour(slots[0]?.[0] ?? 8)}"><small>Свободные интервалы: ${h(slots.map(slot=>hour(slot[0])+'–'+hour(slot[1])).join(', ')||'нет свободных интервалов')}</small></div><div id="form-error" class="error-text" role="alert"></div><div class="dialog-actions"><button class="primary">Добавить в график</button></div></form>`);$('#claim-form').onsubmit=event=>{event.preventDefault();mutate($('#claim-form button'),'claim',[task.id,day(),asHour($('#claim-start').value)]);};
}
function field(name,label,type='text',value='',extra='') { return `<div class="field"><label for="${name}">${h(label)}</label><input id="${name}" name="${name}" type="${type}" value="${h(value)}" ${extra}></div>`; }
function options(items,selected='',placeholder='Выберите…') { return `<option value="">${h(placeholder)}</option>`+items.map(item=>`<option value="${h(item.id)}" ${String(selected)===String(item.id)?'selected':''}>${h(item.name)}</option>`).join(''); }
function createTask(existing=null) {
  const workers=state.snapshot.users.filter(p=>p.role==='worker'&&p.active);const today=day();
  showDialog(existing?'Переназначить наряд':'Выдать наряд',existing?`НР-${existing.id}`:'Быстрое назначение · подробности можно уточнить ниже',`<form id="create-form"><div class="notice">Перед выдачей наряда проверьте участок, оборудование и назначенную смену. При назначении бригаде укажите ответственного сотрудника.</div>${!existing&&refs('work_order_templates').length?`<div class="field"><label for="work-template">Шаблон работы из открытой документации</label><select id="work-template">${options(refs('work_order_templates').map(t=>({id:t.template_id,name:t.title})), '', 'Без шаблона')}</select></div><div id="template-note" class="notice" hidden>Шаблон — черновик для мастера. Проверьте применимость к оборудованию и утверждённым правилам предприятия.<label><input id="template-confirm" type="checkbox"> Я проверил описание и параметры этого наряда.</label></div>`:''}${existing?`<h3>${h(existing.title)}</h3>`:''}<div class="form-grid">${!existing?`<div class="field"><label for="site">1. Участок</label><select id="site" required>${options(refs('sites'))}</select></div><div class="field"><label for="equipment">2. Оборудование</label><select id="equipment" required disabled><option value="">Сначала выберите участок</option></select></div>`:''}<div class="field"><label for="worker">${existing?'':'3. '}Ответственный сотрудник</label><select id="worker" required>${options(workers.map(person=>({id:person.id,name:`${person.name} · ${employeeNames[state.snapshot.employee_status[String(person.id)]]||'—'} · ${state.snapshot.tasks.filter(task=>task.worker_id===person.id&&active(task)).length} нарядов`})),existing?.worker_id)}</select><small id="worker-load">График будет подобран по свободному времени.</small></div>${!existing?`<div class="field"><label for="norm">4. Работа по нормативу</label><select id="norm" required>${options(refs('work_norms').map(n=>({...n,name:`${n.equipment_type} · ${n.kind} · ${n.hours} ч`})))}<option value="custom">Своя работа без норматива</option></select></div><div class="field full"><label for="priority">5. Приоритет</label><select id="priority">${Object.entries(priorityNames).map(([key,value])=>`<option value="${key}" ${key==='normal'?'selected':''}>${h(value)}</option>`).join('')}</select></div>`:''}</div><details ${existing?'open':''} id="task-details"><summary>Описание, график и дополнительные параметры</summary><div style="padding-top:18px">${!existing?`<div class="field"><label for="title">Название работы</label><input id="title" minlength="5" maxlength="200" required placeholder="Заполняется по выбранному нормативу"></div><div class="field"><label for="description">Проблема и ожидаемый результат</label><textarea id="description" minlength="10" maxlength="4000" required placeholder="Заполняется по выбранной работе; уточните при необходимости"></textarea></div>`:''}<div class="form-grid"><div class="field"><label for="brigade">Бригада, если требуется</label><select id="brigade">${options(refs('brigades'),existing?.brigade_id,'Индивидуальная работа')}</select></div>${!existing?`<div class="field"><label for="kind">Тип работы</label><select id="kind"><option>Плановая</option><option>Внеплановая</option></select></div>${field('duration','Плановое время, ч','number',1,'min="0.5" max="10" step="0.5" required')}`:''}${field('task-day','День работ','date',existing?.day||today,'required')}${field('start','Начало','time',hour(existing?.start??8),'step="300" required')}${!existing?`<div class="full">${field('deadline','Крайний срок','datetime-local',today+'T18:00','required')}</div>`:''}</div>${existing?'<div class="field"><label for="reassign-reason">Причина переназначения</label><textarea id="reassign-reason" minlength="3" maxlength="1000" required></textarea></div>':''}</div></details>${!existing?'<div class="field"><label for="before-photos">Фото до ремонта, до 5 файлов по 8 МБ</label><input id="before-photos" type="file" accept="image/jpeg,image/png,image/webp" multiple capture="environment"></div>':''}<div id="form-error" class="error-text" role="alert"></div><div class="dialog-actions"><button class="primary">${existing?'Переназначить':'6. Выдать наряд'}</button></div></form>`);
  const updateNorms=()=>{if(!$('#norm'))return;const eq=refs('equipment').find(e=>String(e.id)===$('#equipment').value);$('#norm').innerHTML=options(refs('work_norms').filter(n=>n.equipment_type===eq?.equipment_type&&n.kind===$('#kind').value).map(n=>({...n,name:`${n.equipment_type} · ${n.kind} · ${n.hours} ч`})))+'<option value="custom">Своя работа без норматива</option>';};
  if($('#equipment'))$('#equipment').onchange=updateNorms;if($('#kind'))$('#kind').onchange=updateNorms;
  let planVersion=0;
  const dialogVersion=state.dialogVersion;
  const planTime=async()=>{
    const version=++planVersion;const id=Number($('#worker').value);if(!id)return;
    const duration=Number($('#duration')?.value || existing?.duration || 1);
    let selectedDay=$('#task-day').value;let shift=state.snapshot.shifts[String(id)];let free=state.snapshot.free_slots[String(id)]||[];
    if(!existing&&selectedDay===today&&shift&&asHour(companyDate().toLocaleTimeString('en-GB',{timeZone:'Asia/Qyzylorda',hour:'2-digit',minute:'2-digit',hour12:false}))>=shift.end){const next=new Date(Date.parse(today+'T12:00:00+05:00')+86400000);selectedDay=next.toLocaleDateString('sv-SE',{timeZone:'Asia/Qyzylorda'});$('#task-day').value=selectedDay;}
    if(selectedDay!==today){$('#worker-load').textContent='Проверяем график выбранного дня…';try{[shift,free]=await Promise.all([rpc('shift',[id,selectedDay]),rpc('free_slots',[id,selectedDay])]);}catch(error){if(version===planVersion&&dialogVersion===state.dialogVersion)$('#worker-load').textContent=error.message;return;}}
    if(version!==planVersion||dialogVersion!==state.dialogVersion)return;
    $('#worker-load').textContent=`${selectedDay}. Смена: ${shift?hour(shift.start)+'–'+hour(shift.end):'не назначена'}. Свободно: ${free.map(slot=>hour(slot[0])+'–'+hour(slot[1])).join(', ')||'нет интервалов'}`;
    if(!existing){const slot=free.find(([start,end])=>end-start>=duration);if(slot){$('#start').value=hour(slot[0]);$('#worker-load').textContent+=` Назначение: ${hour(slot[0])}–${hour(slot[0]+duration)}.`;}else{$('#task-details').open=true;$('#worker-load').textContent+=' Для этой длительности нет подходящего окна — выберите другой день.';}if(shift)$('#deadline').value=selectedDay+'T'+hour(shift.end);}
  };
  if($('#site'))$('#site').onchange=()=>{const site=refs('sites').find(item=>String(item.id)===$('#site').value);$('#equipment').disabled=!site;$('#equipment').innerHTML=options(refs('equipment').filter(item=>String(item.site_id)===String(site?.id)||item.site===site?.name));updateNorms();};
  $('#worker').onchange=planTime;$('#task-day').onchange=planTime;if(existing)planTime();
  if($('#norm'))$('#norm').onchange=()=>{const norm=refs('work_norms').find(item=>String(item.id)===$('#norm').value);if(!norm){if($('#norm').value==='custom')$('#task-details').open=true;return;}if(norm.hours)$('#duration').value=norm.hours;$('#kind').value=norm.kind;if(!$('#title').value.trim()||$('#title').dataset.autofill==='yes'){$('#title').value=`${norm.kind} обслуживание ${norm.equipment_type}`;$('#title').dataset.autofill='yes';}if(!$('#description').value.trim()||$('#description').dataset.autofill==='yes'){$('#description').value=norm.description || `Выполнить работу «${norm.kind} обслуживание ${norm.equipment_type}» на выбранном оборудовании. Проверить результат, зафиксировать неисправность и использованные материалы в отчёте.`;$('#description').dataset.autofill='yes';}planTime();};
  if($('#work-template'))$('#work-template').onchange=()=>{
    const template=refs('work_order_templates').find(t=>String(t.template_id)===$('#work-template').value);
    $('#template-note').hidden=!template;$('#template-confirm').required=Boolean(template);$('#template-confirm').checked=false;
    if(!template)return;
    let requirements=template.closeout_requirements;try{if(typeof requirements==='string')requirements=JSON.parse(requirements);}catch(_){requirements=[];}
    $('#title').value=template.title;$('#title').dataset.autofill='no';
    $('#description').value=template.problem_description+(Array.isArray(requirements)&&requirements.length?'\nТребования к отчёту: '+requirements.join('; '):'');$('#description').dataset.autofill='no';
    $('#kind').value=template.kind;updateNorms();$('#norm').value='custom';$('#task-details').open=true;
  };
  if($('#title'))$('#title').oninput=()=>$('#title').dataset.autofill='no';if($('#description'))$('#description').oninput=()=>$('#description').dataset.autofill='no';
  if($('#duration'))$('#duration').onchange=planTime;
  if($('#priority'))$('#priority').onchange=()=>{$('#kind').value=$('#priority').value==='urgent'?'Внеплановая':'Плановая';};
  $('#create-form').addEventListener('invalid',event=>{if(event.target.closest('details'))$('#task-details').open=true;},true);
  $('#create-form').onsubmit=async event=>{event.preventDefault();const worker=Number($('#worker').value);const brigade=$('#brigade').value?Number($('#brigade').value):null;const selectedDay=$('#task-day').value;const start=asHour($('#start').value);if(existing){mutate($('#create-form button'),'reassign_task',[existing.id,worker,selectedDay,start,$('#reassign-reason').value],{brigade_id:brigade});return;}const site=refs('sites').find(item=>String(item.id)===$('#site').value);const equipment=refs('equipment').find(item=>String(item.id)===$('#equipment').value);let photos=[];try{const files=[...$('#before-photos').files];if(files.length>5||files.some(f=>f.size>8*1024*1024))throw new Error('До 5 фотографий по 8 МБ.');photos=await Promise.all(files.map(async f=>({name:f.name,content:await fileData(f)})));}catch(error){$('#form-error').textContent=error.message;return;}mutate($('#create-form button'),'create_task',[],{title:$('#title').value,description:$('#description').value,site:site?.name,equipment:equipment?.name,priority:$('#priority').value,kind:$('#kind').value,duration:Number($('#duration').value),day:selectedDay,start,deadline:$('#deadline').value,worker_id:worker,site_id:site?.id,equipment_id:equipment?.id,brigade_id:brigade,norm_id:$('#norm').value&&$('#norm').value!=='custom'?Number($('#norm').value):null},photos);};
}

async function openReportForm(task) {
  const sessionToken=state.token;
  const entryVersion=state.dialogVersion;
  let saved;try{saved=await draftGet(draftKey(task.id));}catch(_){toast('Браузер не разрешил хранение черновиков. Не закрывайте форму до отправки.',true);}
  if(!state.user||sessionToken!==state.token||entryVersion!==state.dialogVersion)return;
  const prior=taskReport(task.id);const draft=saved || {work:prior?.status==='revision'?prior.work:'',result:prior?.status==='revision'?prior.result:'',defect:prior?.defect||'',hours:prior?.hours||task.duration,materials:prior?.status==='revision'?prior.materials:[],photos:[],pending:null};
  showDialog('Отчёт о выполнении',`НР-${task.id} · ${task.equipment}`,`<form id="report-form"><div class="notice ${task.status==='revision'?'warning':''}">${task.status==='revision'?`Замечание мастера: ${h(prior?.comment||'Исправьте отчёт')}`:'Опишите фактические работы и результат контрольной проверки. Мастер принимает окончательное решение.'}</div><div id="pending-notice"></div><fieldset id="report-fields"><div class="field"><label for="work">Что выполнено *</label><textarea id="work" minlength="10" maxlength="10000" required placeholder="Узел, выполненные действия, устранённая проблема">${h(draft.work)}</textarea></div><div class="field"><label for="result">Результат контрольной проверки *</label><textarea id="result" minlength="3" maxlength="10000" required placeholder="Как проверили работоспособность и что получили">${h(draft.result)}</textarea></div><div class="form-grid"><div class="field"><label for="defect">Шифр неисправности</label><select id="defect" required>${options(refs('defect_codes').map(item=>({...item,name:`${item.code || ''} · ${item.name}`})),refs('defect_codes').find(item=>draft.defect===`${item.code} · ${item.name}`||draft.defect===item.name)?.id,'Выберите шифр')}</select></div>${field('hours','Фактическое время, ч *','number',draft.hours,'min="0.1" max="24" step="0.1" required')}</div><section class="form-section"><div class="section-head"><h3>Использованные материалы</h3><button id="add-material" type="button">Добавить</button></div><div id="materials"></div><small>Выберите материал или впишите свой. Для нового материала укажите единицу и цену; мастер проверит запись. Если материалы не использовались, оставьте список пустым.</small></section><section class="form-section"><h3>Фотографии результата ${task.kind==='Внеплановая'?'*':''}</h3><p class="muted">${task.kind==='Внеплановая'?'Для закрытия внеплановой работы обязательно фото после выполнения. Неполный отчёт можно отправить для уточнения.':'Приложите фото результата, если требуется для подтверждения.'} До 5 фото JPG, PNG или WebP, до 8 МБ каждое. Исходные файлы сохраняются без изменения.</p><label for="photo-input">Снять или выбрать фотографию</label><input id="photo-input" type="file" accept="image/jpeg,image/png,image/webp" capture="environment" multiple><div id="draft-photos" class="photo-grid"></div></section></fieldset><p id="draft-status" class="sync-note" role="status">${saved?'Черновик восстановлен на этом устройстве.':'Черновик сохраняется на этом устройстве.'}</p><div id="form-error" class="error-text" role="alert"></div><div class="dialog-actions"><button type="button" id="save-draft">Сохранить черновик</button><button id="submit-report" type="submit" class="primary">Отправить мастеру</button></div></form>`);
  state.draft=draft;state.taskId=task.id;renderMaterials();renderDraftPhotos();renderPending();
  $('#report-fields').addEventListener('input',()=>saveDraftSoon());$('#report-fields').addEventListener('change',()=>saveDraftSoon());
  $('#add-material').onclick=()=>{captureDraft();state.draft.materials.push({name:'',quantity:1,unit:'',price:0});renderMaterials();saveDraftSoon();};
  $('#save-draft').onclick=async()=>{try{await persistDraft();toast('Черновик сохранён');}catch(_){toast('Не удалось сохранить черновик: проверьте свободное место в браузере.',true);}};
  $('#photo-input').onchange=async event=>{
    const editingDraft=state.draft;const sessionToken=state.token;const files=[...event.target.files];event.target.value='';if(editingDraft.photos.length+files.length>5){toast('Можно приложить до 5 фотографий.',true);return;}
    for(const file of files){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024){toast('Фото: JPG, PNG или WebP до 8 МБ.',true);continue;}try{const content=await fileData(file);if(state.draft!==editingDraft||state.token!==sessionToken)return;editingDraft.photos.push({name:file.name,content,type:file.type});}catch(_){toast('Не удалось прочитать фото.',true);}}
    renderDraftPhotos();await persistDraft().catch(()=>toast('Фото не сохранились в черновике: возможно, заполнено хранилище браузера.',true));
  };
  $('#report-form').onsubmit=event=>{event.preventDefault();submitReport(task);};
}
function fileData(file) { return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);}); }
function captureDraft() {
  if(!state.draft||!$('#report-form')||state.draft.pending)return;
  state.draft.work=$('#work').value;state.draft.result=$('#result').value;state.draft.hours=Number($('#hours').value);
  const defect=refs('defect_codes').find(item=>String(item.id)===$('#defect').value);state.draft.defect=defect?`${defect.code || ''} · ${defect.name}`:'';
  state.draft.materials=$$('[data-material-row]').map(row=>{const name=$('[data-material-name]',row).value.trim();const item=refs('materials').find(m=>m.name===name);return {material_id:item?.id??null,name,quantity:Number($('[data-material-qty]',row).value),unit:item?.unit||$('[data-material-unit]',row).value.trim(),price:item?Number(item.unit_price):Number($('[data-material-price]',row).value)};});
}
function renderMaterials() {
  const node=$('#materials');if(!node||!state.draft)return;
  node.innerHTML=`<datalist id="material-options">${refs('materials').map(m=>`<option value="${h(m.name)}"></option>`).join('')}</datalist>`+state.draft.materials.map((m,i)=>{const item=refs('materials').find(x=>x.id===m.material_id||x.name===m.name);return `<div class="material-row custom-material" data-material-row="${i}"><label>Материал<input data-material-name list="material-options" maxlength="200" required value="${h(m.name)}" placeholder="Выберите или напишите"></label><label>Количество<input data-material-qty type="number" min="0.001" max="1000000" step="any" required value="${h(m.quantity)}"></label><label>Единица<input data-material-unit maxlength="20" required value="${h(m.unit||'шт.')}" placeholder="шт., кг, л"></label><label>Цена, тг<input data-material-price type="number" min="0" max="100000000" step="any" required value="${h(item?.unit_price_known===false?'':(m.price??0))}" placeholder="${item?.unit_price_known===false?'Цена не подтверждена':''}"></label><button type="button" data-remove-material="${i}" aria-label="Удалить материал ${i+1}">${icon('close')}</button></div>`;}).join('');
  $$('[data-material-name]').forEach(input=>input.onchange=()=>{const item=refs('materials').find(m=>m.name===input.value);const row=input.closest('[data-material-row]');if(item){$('[data-material-unit]',row).value=item.unit;const price=$('[data-material-price]',row);price.value=item.unit_price_known===false?'':item.unit_price;price.placeholder=item.unit_price_known===false?'Цена не подтверждена':'';if(item.unit_price_known===false)toast('Цену этого материала должен подтвердить администратор в справочнике.',true);}});
  $$('[data-remove-material]').forEach(button=>button.onclick=()=>{captureDraft();state.draft.materials.splice(Number(button.dataset.removeMaterial),1);renderMaterials();saveDraftSoon();});
}

function renderDraftPhotos() {
  if(!$('#draft-photos')||!state.draft)return;
  $('#draft-photos').innerHTML=state.draft.photos.map((photo,index)=>`<div class="photo-tile"><img src="data:${h(photo.type||'image/jpeg')};base64,${h(photo.content)}" alt="Фотография результата ${index+1}"><span>${h(photo.name)}</span>${state.draft.pending?'':`<button type="button" data-remove-photo="${index}" aria-label="Удалить фото ${index+1}">${icon('close')}</button>`}</div>`).join('');
  $$('[data-remove-photo]').forEach(button=>button.onclick=()=>{state.draft.photos.splice(Number(button.dataset.removePhoto),1);renderDraftPhotos();saveDraftSoon();});
}
let saveTimer;
function saveDraftSoon() { clearTimeout(saveTimer);saveTimer=setTimeout(()=>persistDraft().catch(()=>{if($('#draft-status'))$('#draft-status').textContent='Не удалось сохранить черновик. Не закрывайте форму.';}),300); }
async function persistDraft() {
  if(!state.draft||!state.taskId||!state.user)return;captureDraft();const key=draftKey(state.taskId);const draft=structuredClone(state.draft);await draftWrite(key,draft);if($('#draft-status'))$('#draft-status').textContent=`Черновик сохранён ${new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}`;
}
function renderPending() {
  const pending=Boolean(state.draft?.pending);if(!$('#report-fields'))return;
  $('#report-fields').disabled=pending;$('#save-draft').disabled=pending;$('#submit-report').textContent=pending?'Повторить отправку':'Отправить мастеру';
  $('#pending-notice').innerHTML=pending?'<div class="notice warning">Результат предыдущей отправки пока не подтверждён. Повторите запрос: используется тот же идентификатор, чтобы не создать второй отчёт. До получения ответа данные зафиксированы.</div>':'';renderDraftPhotos();
}
async function submitReport(task) {
  if(state.busy)return;captureDraft();const draft=state.draft;
    state.busy=true;$('#submit-report').disabled=true;$('#form-error').textContent='';
  if(!draft.pending)draft.pending={request_id:uuid(),args:[task.id],kwargs:{work:draft.work,result:draft.result,defect:draft.defect,hours:draft.hours,materials:draft.materials},photos:draft.photos.map(({name,content})=>({name,content}))};
  renderPending();$('#submit-report').textContent='Отправляем…';
  let transportStarted=false;
  // Save the exact payload before transport. Retrying after a lost response sends the same request_id.
  try{await persistDraft();const pending=draft.pending;transportStarted=true;await rpc('submit',pending.args,pending.kwargs,pending.photos,pending.request_id);await draftDelete(draftKey(task.id));state.draft=null;state.taskId=null;$('#dialog').close();toast('Отчёт отправлен. Он появится на проверке у мастера.');await refresh(true);}
  catch(error){if(!transportStarted||error instanceof APIError&&error.status>=400&&error.status<500){draft.pending=null;}$('#form-error')&&($('#form-error').textContent=transportStarted?error.message:'Не удалось сохранить запрос до отправки. Проверьте свободное место в браузере или уменьшите количество фотографий; данные ещё не отправлены.');await persistDraft().catch(()=>{});renderPending();}
  finally{state.busy=false;if($('#submit-report'))$('#submit-report').disabled=false;}
}
function findingText(finding) { return typeof finding==='string'?finding: finding.message||finding.description||finding.text||({mandatory_after_photo_missing:'Не хватает фото после внеплановой работы',duplicate_other_task:'Фото уже использовано в другом наряде',captured_before_issue:'Фото снято до выдачи наряда',capture_time_unknown:'Время съёмки неизвестно',invalid_exif_time:'Некорректная дата съёмки'}[finding.code])||JSON.stringify(finding); }
function aiBlock(report) {
  const ai=report.ai||{};const checks=report.photo_issues||[];
  const checksHTML=checks.filter(check=>check.id!=='photo_metadata').map(check=>`<div class="finding"><strong>${check.severity==='warn'?'Требует уточнения':check.severity==='block'?'Не хватает данных':'Проверка данных'}</strong><br>${h(findingText(check))}${['work','result','photos','materials','defect'].includes(check.field)?` <a href="#review-${h(check.field)}">Открыть поле</a>`:''}${check.source_report_id&&state.user.role!=='worker'?`<br><button data-evidence="${Number(check.source_report_id)}">Сравнить с ОТ-${Number(check.source_report_id)}</button>`:''}</div>`).join('');
  if(['queued','processing'].includes(ai.status)||report.status==='aiPending')return '<div class="notice">ИИ проверяет отчёт. Итог появится после обновления данных. Самостоятельно подтверждать результат ИИ не может.</div>'+checksHTML;
  if(ai.status!=='completed')return `<div class="notice warning"><strong>Ручная проверка мастером</strong><br>${h(ai.error||'Проверка ИИ для этого отчёта не выполнялась.')}<br>Отчёт доступен для решения мастера.</div>${checksHTML}`;
  return `<div class="section-head"><h3>Предварительная оценка ИИ</h3><span class="score">${ai.score??'—'}<small style="font-size:14px"> / 100</small></span></div><p>${h(ai.summary||'')}</p>${(ai.findings||[]).map(finding=>{const field=typeof finding==='object'?finding.field:null;return `<div class="finding">${h(findingText(finding))}${['work','result','photos','materials','defect'].includes(field)?` <a href="#review-${h(field)}">Открыть данные</a>`:''}</div>`;}).join('')}${checksHTML}<small>${h(ai.model||'Локальная модель')} · рекомендация, решение принимает мастер</small>`;
}
async function openReport(id) {
  const report=state.snapshot.reports.find(r=>r.id===id);if(!report)return;const task=taskById(report.task_id);const canReview=canManage()&&report.status==='submitted';
  const version=showDialog('Приёмка результата',`ОТ-${report.id} · НР-${report.task_id}`,`<div class="badges">${badge(report.status)}${task?badge(task.priority,'priority'):''}</div><div class="split-report"><div><section class="card"><h3>${h(report.title)}</h3><p class="muted">${h(report.worker_name)} · ${h(report.equipment)}</p>${task?`<div class="notice"><strong>Исходная задача</strong><br>${h(task.description)}</div>`:''}<h3 id="review-work">Выполненные действия</h3><p class="work-text">${h(report.work)}</p><h3 id="review-result">Контрольная проверка</h3><p class="work-text">${h(report.result)}</p><div class="definition"><div id="review-defect"><small>Неисправность</small><p>${h(report.defect||'Не указана')}</p></div><div><small>Фактическое время</small><p>${h(report.hours)} ч</p></div></div><h3 id="review-materials">Материалы</h3>${report.materials.length?`<ul>${report.materials.map(material=>`<li>${h(material.name)} — ${h(material.quantity)} ${h(material.unit)}</li>`).join('')}</ul>`:'<p class="muted">Не использовались</p>'}<h3 id="review-photos">Фото результата</h3><div class="photo-grid">${report.photos.map((name,index)=>`<div class="photo-tile"><img data-photo="${h(name)}" alt="Фотография отчёта ${index+1}"><span>Загрузка фото…</span></div>`).join('')}</div>${report.photos.length?'':'<p class="muted">Фотографии не приложены</p>'}</section></div><div class="sticky-decision"><section class="card" id="ai-verdict">${aiBlock(report)}</section><section class="card" style="margin-top:16px"><h3>Решение мастера</h3>${canReview?`<form id="review-form"><div class="field"><label for="review-comment">Комментарий сотруднику *</label><textarea id="review-comment" required minlength="3" maxlength="10000" placeholder="Что принято или что нужно доработать"></textarea></div>${field('review-score','Итоговая оценка, 0–100','number',report.ai?.score??'','min="0" max="100" step="1" required')}<small>Можно подтвердить оценку ИИ или выставить свою. Возврат на доработку не начисляет оценку.</small><div id="form-error" class="error-text" role="alert"></div><div class="dialog-actions"><button id="revise-report" class="danger" type="button">На доработку</button><button id="approve-report" class="primary">Принять</button></div></form>`:report.comment?`<p class="work-text">${h(report.comment)}</p><p>${report.score!=null?`<strong>${report.score}/100</strong> · `:''}${h(report.reviewer_name||'Мастер')} · ${h(dateTime(report.reviewed))}</p>`:'<p class="muted">Решение появится после проверки мастером.</p>'}</section></div></div>`);
  state.reportDialog=id;loadPhotos(version);try{const rows=await rpc('photos_for_task',[report.task_id]);if(version===state.dialogVersion){const before=rows.filter(p=>p.kind==='before');if(before.length){$('#review-photos').insertAdjacentHTML('beforebegin',`<h3>Фото до ремонта</h3><div class="photo-grid">${before.map(p=>`<div class="photo-tile"><img data-photo="${h(p.object_key)}" alt="Фото до ремонта"><span>Фото до ремонта</span></div>`).join('')}</div>`);loadPhotos(version);}}}catch(_){/* after photos remain available; server warnings are shown above */}if(version!==state.dialogVersion)return;bindCommon($('#ai-verdict'));if(canReview){const saved=state.reviewDrafts.get(id);if(saved){$('#review-comment').value=saved.comment;$('#review-score').value=saved.score;}$('#review-form').addEventListener('input',()=>state.reviewDrafts.set(id,{comment:$('#review-comment').value,score:$('#review-score').value}));}
  if(canReview){$('#review-form').onsubmit=event=>{event.preventDefault();mutate($('#approve-report'),'review',[report.id,true,Number($('#review-score').value),$('#review-comment').value]);};$('#revise-report').onclick=()=>{if($('#review-comment').value.trim().length<3){$('#form-error').textContent='Добавьте понятный комментарий от 3 символов.';$('#review-comment').focus();return;}mutate($('#revise-report'),'review',[report.id,false,0,$('#review-comment').value]);};}
}
function updateOpenReport() { if(!state.reportDialog||!$('#dialog').open)return;const report=state.snapshot.reports.find(r=>r.id===state.reportDialog);if(report&&$('#ai-verdict')){$('#ai-verdict').innerHTML=aiBlock(report);bindCommon($('#ai-verdict'));if(report.status==='submitted'&&canManage()&&!$('#review-form')){$('#ai-verdict').insertAdjacentHTML('beforeend','<button class="primary" id="begin-review" style="margin-top:14px">Перейти к решению мастера</button>');$('#begin-review').onclick=()=>openReport(report.id);}} }
async function loadPhotos(version) {
  const sessionToken=state.token;
  for(const img of $$('[data-photo]')){
    const name=img.dataset.photo;
    try{
      let url=state.photoURLs.get(name);
      if(!url){const response=await fetch(`/api/photos/${encodeURIComponent(name)}`,{headers:{Authorization:`Bearer ${sessionToken}`},cache:'no-store'});if(!response.ok)throw new Error('Фото недоступно');url=URL.createObjectURL(await response.blob());if(!state.user||state.token!==sessionToken){URL.revokeObjectURL(url);return;}state.photoURLs.set(name,url);}
      if(version!==state.dialogVersion)return;img.src=url;img.nextElementSibling.textContent=img.alt.includes('до ремонта')?'Фото до ремонта':'Фото результата';img.onclick=()=>{const reportId=state.reportDialog;showDialog('Фотография результата','Отчёт сотрудника',`<img src="${h(url)}" alt="Фото результата в полном размере" style="max-width:100%;max-height:75dvh;display:block;margin:auto">${reportId?'<button id="return-report" style="margin-top:16px">Вернуться к отчёту</button>':''}`);if($('#return-report'))$('#return-report').onclick=()=>openReport(reportId);};img.style.cursor='zoom-in';
    }catch(_){if(img.isConnected)img.nextElementSibling.textContent='Фото недоступно — проверьте сеть';}
  }
}
