async function calculateAnalytics() {
 const node=$('#analytics-result');state.analyticsStart=$('#analytics-start').value;state.analyticsEnd=$('#analytics-end').value;
 const end=new Date(Date.parse(state.analyticsEnd+'T12:00:00+05:00')+86400000).toLocaleDateString('sv-SE',{timeZone:'Asia/Qyzylorda'});
 try{const d=await rpc('analytics',[state.analyticsStart,end]);if(!node.isConnected)return;
 node.innerHTML=`<div class="metric-row">${metric(d.counts.issued,'Выдано')}${metric(d.counts.completed,'Выполнено')}${metric(d.counts.completed_late,'С опозданием')}${metric(d.counts.rejected,'Отказы')}</div><section class="card"><h2>Рейтинг исполнителей</h2>${d.workers.filter(w=>w.done).map(w=>`<p>${h(w.name)} · ${w.score}/100 · ${w.done} закрыто</p>`).join('')||'<p>Нет принятых работ</p>'}<h2>Рейтинг бригад</h2>${d.brigades.map(b=>`<p>${h(b.name)} · ${b.score}/100 · ${b.done} закрыто</p>`).join('')||'<p>Нет принятых бригадных работ</p>'}<h2>Частые ремонты</h2>${d.failures.slice(0,10).map(f=>`<p>${h(refs('equipment').find(e=>e.id===f.equipment_id)?.name)} · ${f.repairs} ремонтов <button data-equipment="${f.equipment_id}">История</button></p>`).join('')}<h2>Расход материалов</h2>${d.materials.map(m=>`<p>${h(m.name)} · ${m.quantity} ${h(m.unit)} · ${m.cost} тг</p>`).join('')}<p class="sync-note">Качество 40%, сроки 25%, доработки 15%, сложность и объём 15%, отказы 5%. Данные демонстрационные; формулу необходимо согласовать с заказчиком.</p></section>`;bindCommon(node);
 }catch(error){if(node.isConnected)node.textContent=error.message;}
}
