if('serviceWorker' in navigator && window.isSecureContext)navigator.serviceWorker.register('/sw.js',{scope:'/'}).catch(()=>{});
if(state.token&&state.user){renderShell();refresh(true);}else renderLogin();
const chatState={cid:'',items:[],conversations:[],busy:false,pending:false,signature:'',draft:'',error:'',replyId:'',newId:''};
let workspacePolling=false;
const chatId=()=>uuid().replaceAll('-','');
function safeChatText(text){return h(text).replace(/https?:\/\/[^\s<>]+/g,url=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${url}</a>`).replace(/\n/g,'<br>');}
function chatPage(){return pageHead('Помощник НарядAI','Наряды, история ремонтов и инструкции. ИИ объясняет; решения принимает человек.')+`<div class="chat-layout"><aside class="card chat-sidebar"><button id="new-chat" class="primary">${icon('plus')} Новый чат</button><div id="conversation-list" class="conversation-list"></div><button data-go="knowledge">Документация</button></aside><section class="card chat-main"><div id="chat-status" class="chat-status" role="status">Подключаемся…</div><div id="chat-messages" class="chat-messages" role="log" aria-label="Сообщения чата"></div><form id="chat-form" class="chat-composer"><label class="sr-only" for="chat-message">Сообщение ИИ</label><textarea id="chat-message" maxlength="4000" rows="3" placeholder="Например: какие неисправности повторялись за месяц?">${h(chatState.draft)}</textarea><div class="composer-footer"><small>Ctrl + Enter · ответ на основе доступных данных</small><button id="chat-send" class="primary">${icon('arrow')} Отправить</button></div><div id="chat-error" class="error-text" role="alert"></div></form></section></div>`;}
async function pollChat(){if(!state.user||state.page!=='chat'||chatState.busy)return;const token=state.token;chatState.busy=true;try{const result=await request('/api/chat'+(chatState.cid?'?conversation_id='+chatState.cid:''));if(state.token!==token||state.page!=='chat')return;chatState.cid=result.conversation_id;chatState.items=result.messages;chatState.pending=result.pending;paintChat(result);const list=await request('/api/chat/conversations');if(state.token!==token||state.page!=='chat')return;chatState.conversations=list.items;paintConversations();}catch(e){if($('#chat-error'))$('#chat-error').textContent=e.message;}finally{chatState.busy=false;}}
function paintConversations(){const node=$('#conversation-list');if(!node)return;node.innerHTML=chatState.conversations.map(c=>`<button data-conversation="${h(c.id)}" ${c.id===chatState.cid?'aria-current="page"':''}>${h(c.title.slice(0,55))}<small>${new Date(c.created*1000).toLocaleDateString('ru-RU')}</small></button>`).join('');$$('[data-conversation]').forEach(b=>b.onclick=()=>{if(chatState.busy)return;chatState.draft=$('#chat-message')?.value||'';chatState.cid=b.dataset.conversation;chatState.signature='';pollChat();});}
function paintChat(result){const status=$('#chat-status'),node=$('#chat-messages');if(!status||!node)return;status.textContent=!result.ai_enabled?'ИИ выключен администратором':!result.online?'Компьютер с ИИ не подключён':result.pending?'ИИ обрабатывает запрос…':'ИИ подключён · база и документация доступны';$('#chat-send').disabled=result.pending||!result.ai_enabled;const signature=JSON.stringify(result.messages);if(signature===chatState.signature&&node.childElementCount)return;const bottom=node.scrollHeight-node.scrollTop-node.clientHeight<60;chatState.signature=signature;node.innerHTML=result.messages.map(m=>`<article class="chat-turn"><div class="chat-bubble user"><small>Вы</small><div>${safeChatText(m.message)}</div></div>${m.status==='completed'?`<div class="chat-bubble assistant"><small>НарядAI · ${h(m.model)}</small><div>${safeChatText(m.answer)}</div><button data-copy-answer="${h(m.id)}" class="ghost">Копировать</button></div>`:m.status==='failed'?`<div class="chat-bubble failure"><strong>Ответ не получен</strong><div>${h(m.error)}</div><button data-retry-chat="${h(m.id)}">Повторить вопрос</button></div>`:`<div class="chat-bubble assistant pending"><span class="spinner"></span> ${m.status==='queued'?'Ожидает обработчика':'Модель готовит ответ'} · ${Math.max(0,Math.floor(Date.now()/1000-m.created))} сек</div>`}</article>`).join('')||`<div class="chat-welcome"><h2>Что проверить в вашей смене?</h2><p>Задайте вопрос по наряду, оборудованию или инструкции.</p><div class="chat-suggestions">${['Покажи текущие задачи','Какие неисправности повторяются за месяц?','Объясни, как оцениваются отчёты'].map(q=>`<button data-suggest="${h(q)}">${h(q)}</button>`).join('')}</div></div>`;if(bottom)node.scrollTop=node.scrollHeight;$$('[data-suggest]').forEach(b=>b.onclick=()=>{$('#chat-message').value=b.dataset.suggest;$('#chat-message').focus();});$$('[data-copy-answer]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(chatState.items.find(m=>m.id===b.dataset.copyAnswer).answer);toast('Ответ скопирован');}catch(_){toast('Выделите ответ и скопируйте вручную');}});$$('[data-retry-chat]').forEach(b=>b.onclick=()=>{$('#chat-message').value=chatState.items.find(m=>m.id===b.dataset.retryChat).message;$('#chat-message').focus();});}
async function sendChat(event){event?.preventDefault();if(chatState.busy||chatState.pending)return;const editor=$('#chat-message');const message=editor.value.trim();if(!message)return;const token=state.token;const key=chatState.cid+'\n'+message;if(chatState.replyKey!==key){chatState.replyId=chatId();chatState.replyKey=key;}chatState.busy=true;$('#chat-send').disabled=true;try{const result=await request('/api/chat',{method:'POST',body:JSON.stringify({conversation_id:chatState.cid,request_id:chatState.replyId,message})});if(state.token!==token||state.page!=='chat')return;editor.value='';chatState.draft='';chatState.replyId='';chatState.replyKey='';chatState.pending=result.pending;paintChat(result);}catch(e){if($('#chat-error'))$('#chat-error').textContent=e.message;}finally{chatState.busy=false;}}
function consolePage(){return pageHead('Центр управления','Состояние ИИ, очередь и журнал действий. Команды выполняются от вашего имени.')+`<div id="monitor-cards" class="metric-row"></div><div class="toolbar"><button id="toggle-ai" class="primary">Обновляем статус ИИ…</button><button id="toggle-web">Внешний поиск</button><button data-go="knowledge">Инструкции ИИ</button><button data-go="people">Сотрудники и доступ</button><button id="import-demo" ${state.seedDemo?'':'hidden'}>Добавить учебную базу</button></div><div class="grid cols-2"><section class="card terminal-card"><h2>Консоль поддержки</h2><pre id="console-output" class="terminal" role="log">Введите /help для списка команд.\n</pre><form id="console-form" class="terminal-form"><label class="sr-only" for="console-command">Команда</label><input id="console-command" autocomplete="off" maxlength="2000" placeholder="/help"><button class="primary">Выполнить</button></form></section><section class="card"><h2>Журнал действий</h2><div id="monitor-events" class="event-stream"></div></section></div><section class="card" style="margin-top:20px"><h2>Задания ИИ</h2><div id="monitor-jobs" class="list"></div></section>`;}
let consoleMonitor=null,consoleBusy=false,consoleRetry=null;
async function pollMonitor(){if(state.page!=='console'||!state.user)return;const token=state.token;try{const d=await request('/api/admin/monitor');if(token!==state.token||state.page!=='console')return;consoleMonitor=d;$('#monitor-cards').innerHTML=metric(d.database,'Общая база')+metric(d.counts.tasks,'Нарядов')+metric(d.counts.reports,'Отчётов')+metric(d.worker_online?'На связи':'Не подключён','Обработчик ИИ');$('#toggle-ai').textContent=d.ai_enabled?'Выключить ИИ':'Включить ИИ';$('#toggle-web').textContent=d.web_enabled?'Выключить внешний поиск':'Включить внешний поиск';$('#monitor-events').innerHTML=d.events.map(e=>`<div class="event-item"><small>${h(dateTime(e.created))} · ${h(e.actor||'Система')}${e.task_id?' · НР-'+e.task_id:''}</small><p>${h(e.message)}${e.reason?' · '+h(e.reason):''}</p></div>`).join('')||'<p>Действий пока нет</p>';$('#monitor-jobs').innerHTML=[...d.chat_jobs.map(j=>({...j,label:'Чат '+j.id.slice(0,8)})),...d.report_jobs.map(j=>({...j,label:'ОТ-'+j.report_id}))].map(j=>`<div class="list-row"><div><strong>${h(j.label)}</strong><small>${h(j.status)} · ${h(j.model||'модель ещё не ответила')}</small>${j.error?`<small class="error-text">${h(j.error)}</small>`:''}</div></div>`).join('')||'<p>Очередь пуста</p>';}catch(e){toast(e.message,true);}}
async function executeCommand(command){if(consoleBusy)return;consoleBusy=true;const token=state.token;if(!consoleRetry||consoleRetry.command!==command)consoleRetry={command,request_id:chatId()};try{const d=await request('/api/admin/command',{method:'POST',body:JSON.stringify(consoleRetry)});if(token!==state.token)return;consoleRetry=null;const node=$('#console-output');if(node){node.textContent+='\n> '+command+'\n'+(typeof d.output==='string'?d.output:JSON.stringify(d.output,null,2))+'\n';node.scrollTop=node.scrollHeight;}await pollMonitor();}catch(e){const node=$('#console-output');if(node)node.textContent+='\nОшибка: '+e.message+'\n';else toast(e.message,true);}finally{consoleBusy=false;}}
function knowledgePage(){return pageHead('Документация ИИ','Инструкции хранятся на общем сервере и доступны поиску в чатах.')+`<div class="grid cols-2"><section class="card"><h2>Загруженные документы</h2><div id="knowledge-list">Загрузка…</div></section>${state.user.role==='admin'?`<section class="card"><h2>Добавить инструкцию</h2><form id="knowledge-form"><div class="field"><label for="knowledge-file">Текстовый файл (.txt, .md)</label><input id="knowledge-file" type="file" accept=".txt,.md"></div>${field('knowledge-title','Название','text','','required maxlength="200"')}<div class="field"><label for="knowledge-body">Текст документа</label><textarea id="knowledge-body" required minlength="20" maxlength="100000" rows="12" placeholder="Вставьте утверждённую инструкцию. PDF можно сохранить как текст."></textarea></div><p>Добавляйте проверенные инструкции предприятия. Текст документа не разрешает ИИ менять данные.</p><button class="primary">Сохранить документ</button><div id="knowledge-error" class="error-text" role="alert"></div></form></section>`:''}</div>`;}
async function loadKnowledge(){const token=state.token;try{const d=await request('/api/knowledge');if(token!==state.token||!$('#knowledge-list'))return;$('#knowledge-list').innerHTML=d.items.map(x=>`<div class="list-row"><div><strong>${h(x.title)}</strong><small>${h(dateTime(x.created))} · ${x.size} символов</small></div></div>`).join('')||'<p>Инструкции ещё не загружены.</p>';}catch(e){toast(e.message,true);}}
function bindWorkspace(){if(state.page==='chat'){chatState.signature='';$('#chat-message').oninput=e=>chatState.draft=e.target.value;$('#chat-message').onkeydown=e=>{if(e.ctrlKey&&e.key==='Enter')sendChat(e);};$('#chat-form').onsubmit=sendChat;$('#new-chat').onclick=async()=>{if(chatState.busy)return;const token=state.token;chatState.busy=true;chatState.newId=chatState.newId||chatId();try{const d=await request('/api/chat/new',{method:'POST',body:JSON.stringify({request_id:chatState.newId})});if(state.token!==token||state.page!=='chat')return;chatState.cid=d.conversation_id;chatState.newId='';chatState.draft='';$('#chat-message').value='';chatState.signature='';paintChat(d);}catch(e){toast(e.message,true);}finally{chatState.busy=false;pollChat();}};pollChat();}if(state.page==='console'){pollMonitor();$('#import-demo').onclick=async()=>{if(!confirm('Добавить учебные записи? Существующие пользователи и наряды сохранятся. Повторный импорт ничего не добавляет.'))return;const b=$('#import-demo');b.disabled=true;try{const r=await request('/api/admin/import-demo',{method:'POST',body:'{}'});toast('Учебная база: '+r.tasks+' нарядов, '+r.reports+' отчётов');await pollMonitor();}catch(e){toast(e.message,true);}finally{b.disabled=false;}};$('#console-form').onsubmit=e=>{e.preventDefault();const input=$('#console-command');const command=input.value.trim();if(command){executeCommand(command);input.value='';}};$('#toggle-ai').onclick=()=>consoleMonitor&&executeCommand('/ai '+(consoleMonitor.ai_enabled?'off':'on'));$('#toggle-web').onclick=()=>consoleMonitor&&executeCommand('/web '+(consoleMonitor.web_enabled?'off':'on'));}if(state.page==='knowledge'){loadKnowledge();if($('#knowledge-file'))$('#knowledge-file').onchange=async e=>{const f=e.target.files[0];if(f){if(f.size>500000){toast('Файл слишком большой',true);return;}$('#knowledge-body').value=await f.text();$('#knowledge-title').value=f.name;}};if($('#knowledge-form'))$('#knowledge-form').onsubmit=async e=>{e.preventDefault();const button=$('#knowledge-form button');button.disabled=true;const payload={title:$('#knowledge-title').value,body:$('#knowledge-body').value,request_id:chatId()};try{await request('/api/knowledge',{method:'POST',body:JSON.stringify(payload)});$('#knowledge-body').value='';$('#knowledge-title').value='';await loadKnowledge();toast('Инструкция добавлена');}catch(error){$('#knowledge-error').textContent=error.message;}finally{button.disabled=false;}};}}
setInterval(()=>{if(!workspacePolling){workspacePolling=true;Promise.resolve(state.page==='chat'?pollChat():state.page==='console'?pollMonitor():null).finally(()=>workspacePolling=false);}},3000);

setInterval(()=>{if(state.user)refresh();},3000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.user)refresh();});
